import org.springframework.stereotype.Component;
import org.springframework.web.server.ResponseStatusException;

/**
 * Rejects creating an owner when the owner's city already contains 50 or more owners, comparing
 * the city case-insensitively with runs of whitespace collapsed.
 */
@Aspect
@Component
public class OwnerCityCapacityAdvice {

    private static final int CITY_CAPACITY = 50;

    private final ClinicService clinicService;

    public OwnerCityCapacityAdvice(ClinicService clinicService) {
        this.clinicService = clinicService;
    }

    @Before("execution(* org.springframework.samples.petclinic.rest.controller.v1.OwnerRestControllerV1.addOwner(..)) && args(fields)")
    public void rejectFullCity(OwnerFieldsDto fields) {
        String city = normalize(fields.getCity());
        if (city == null) {
            return;
        }
        long owners = clinicService.findAllOwners().stream()
            .filter(existing -> city.equals(normalize(existing.getCity())))
            .count();
        if (owners >= CITY_CAPACITY) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "This city already has the maximum number of owners");
        }
    }

    private static String normalize(String value) {
        return value == null ? null : value.strip().replaceAll("\\s+", " ").toLowerCase();
    }
}
